import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = sum(1 for a in op if a == 'C')
    op_d = n - op_c

    # Endgame: exploit persistent cooperators hard, otherwise secure gains.
    if n >= 97:
        if op_d <= 2:
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'D' if rng.random() < 0.6 else 'C'

    # Pure cooperator detection: they never defected. Build cooperation first,
    # then exploit in the back half to get DC=5.
    if op_d == 0:
        if n < 25:
            return 'C'
        # gradual exploitation with periodic cooperation to keep them nice
        if n < 60:
            return 'D' if rng.random() < 0.25 else 'C'
        if n < 85:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'D'

    # Almost-pure cooperator: only one or two defections ever, and recent ones
    # are not defections. Treat as exploitable.
    if op_d <= 2 and op[-1] == 'C' and n >= 30:
        if n >= 70:
            return 'D' if rng.random() < 0.7 else 'C'
        return 'D' if rng.random() < 0.3 else 'C'

    # Sustained / heavy defector: stop feeding them, defect, but occasionally
    # probe to catch a shift and to avoid an unrecoverable spiral.
    recent = op[-10:]
    recent_d = sum(1 for a in recent if a == 'D')
    recent_c = len(recent) - recent_d

    if op_d >= n - max(1, n // 10) and recent_d >= 1:
        # opponent almost always defects
        if recent_c >= 3 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if recent_d >= 7:
        # heavy recent defection
        if n < 90 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Recovery from mutual defection: if we're both stuck, cooperate to reset.
    last_me, last_op = history[-1]

    if last_op == 'D' and last_me == 'D':
        # break DD loops, especially early/mid game
        if n < 90 and rng.random() < 0.55:
            return 'C'
        return 'D'

    # Opponent defected but we cooperated last: retaliate, with mild
    # forgiveness if their overall record is good.
    if last_op == 'D':
        if op_c >= n - max(2, n // 6):
            # mostly cooperative: forgive quickly
            if rng.random() < 0.35:
                return 'C'
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent cooperated last. If we defected last, repair unless we're
    # farming a cooperator (handled above). Otherwise stay cooperative but
    # probe occasionally.
    if last_me == 'D':
        # Some exploitation is profitable only if they keep cooperating;
        # check recent exploitation yield.
        if n >= 4:
            tail = history[-4:]
            dc = sum(1 for a, b in tail if a == 'D' and b == 'C')
            cd = sum(1 for a, b in tail if a == 'C' and b == 'D')
            if dc >= 2 and cd == 0 and op_d <= max(2, n // 10):
                # they're tolerating exploitation
                if rng.random() < 0.5:
                    return 'D'
        return 'C'

    # Both cooperated. Keep cooperating but rarely probe to detect a shift /
    # farm if opponent is exploitable.
    if n >= 8:
        if op_d <= max(1, n // 12) and n >= 40:
            # very cooperative, start occasional exploitation
            return 'D' if rng.random() < 0.12 else 'C'
        # small probe to detect exploitability
        if rng.random() < 0.03:
            return 'D'
    return 'C'
